import { join } from 'node:path';
import { getExtensionDir } from './definitions.js';

export function getSiteWidgetExtensionsDir(projectFolder: string) {
  return join(getExtensionDir(projectFolder), 'site', 'widgets');
}

export function getSiteWidgetExtensionPath(
  projectFolder: string,
  extensionPath: string
) {
  return join(getSiteWidgetExtensionsDir(projectFolder), extensionPath);
}

